# rule hypothesis: find largest solid same-color rectangle; recolor it to 4. Check both demos.
def rect(g):
    best=None
    for i in range(30):
        for j in range(30):
            c=g[i][j]
            h=w=1
            while i+h<30 and g[i+h][j]==c: h+=1
            while j+w<30 and g[i][j+w]==c: w+=1
            if h*w>=4 and best is None or True:
                pass
    # instead brute force: try every candidate top-left with max expansion? simpler: for each cell expand until non-matching; record maximal runs along row/col separately then combine
    # Actually use connected component of same color as bounding box per component.
    seen=set(); comps=[]
    for i in range(30):
        for j in range(30):
            if (i,j) in seen: continue
            st=[(i,j)]; comp=[]
            while st:
                a,b=st.pop()
                if (a,b) in seen: continue
                seen.add((a,b)); comp.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    ca,cb=a+da,b+db
                    if 0<=ca<30 and 0<=cb<30 and not (ca,cb) in seen and g[ca][cb]==c: st.append((ca,cb))
            comps.append(comp)
    res=[]
    for comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        b=i0=min(rs); e=max(rs); j0=min(cs); e2=max(cs)
        area=(e-b+1)*(e2-j0+1)-len(comp)
        res.append((comp,(b,j0,e2-j0+1)))
    return res
