    out=[r[:] for r in g]
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W-1):
            c=g[i][j]
            if g[i][j+1]!=c: continue
            L=1
            while j+L<W and g[i][j+L]==c: L+=1
            if L<2: continue
            h=1
